"""mpl_toolkits.axisartist.floating_axes — floating axes."""

from mpl_toolkits.axisartist.axislines import Axes

class FloatingAxes(Axes):
    name = 'floatingaxes'

class FloatingSubplot(FloatingAxes):
    pass

class FloatingAxesBase:
    pass

def floatingaxes_class_factory(axes_class=None):
    return FloatingAxes


# ─── Added: missing floating_axes helpers ───────────────────────────


class ExtremeFinderFixed:
    """Returns a fixed set of extremes regardless of the input window —
    used for axes whose limits are externally fixed."""

    def __init__(self, extremes):
        self.extremes = tuple(extremes)

    def __call__(self, *args, **kwargs):
        return self.extremes


class FixedAxisArtistHelper:
    """Axis artist helper pinned to a fixed coordinate (curvilinear
    variant of FixedAxisArtistHelperRectilinear)."""

    def __init__(self, grid_helper, side, nth_coord_ticks=None):
        self.grid_helper = grid_helper
        self.side = side
        self.nth_coord_ticks = nth_coord_ticks


class FloatingAxisArtistHelper:
    """Axis artist that floats at a data value in curvilinear coords."""

    def __init__(self, grid_helper, nth_coord, value, axis_direction='bottom'):
        self.grid_helper = grid_helper
        self.nth_coord = nth_coord
        self.value = value
        self.axis_direction = axis_direction


class GridHelperCurveLinear:
    """Grid helper for curvilinear projections — passes the transform
    through to compute the gridline positions."""

    def __init__(self, aux_trans, extreme_finder=None, grid_locator1=None,
                 grid_locator2=None, tick_formatter1=None, tick_formatter2=None):
        self.aux_trans = aux_trans
        self.extreme_finder = extreme_finder
        self.grid_locator1 = grid_locator1
        self.grid_locator2 = grid_locator2
        self.tick_formatter1 = tick_formatter1
        self.tick_formatter2 = tick_formatter2

    def new_fixed_axis(self, loc, nth_coord=None, axis_direction=None,
                        offset=None, axes=None):
        return FixedAxisArtistHelper(self, loc, nth_coord)

    def new_floating_axis(self, nth_coord, value, axes=None,
                           axis_direction='bottom'):
        return FloatingAxisArtistHelper(self, nth_coord, value, axis_direction)
